import {accessDenied} from './access.js?v=20261010-member-fixes';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export const dateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
export function monthCells(year,month){const start=new Date(year,month,1);start.setDate(1-start.getDay());return Array.from({length:42},(_,index)=>dateKey(new Date(start.getFullYear(),start.getMonth(),start.getDate()+index)));}
const resultLabels=Object.freeze({scheduled:'경기 전',win:'승',loss:'패',draw:'무승부'});
class GameResultError extends Error{}
export function parseGameResult(status,holics,opponent){
  if(!Object.hasOwn(resultLabels,status))throw new GameResultError('경기 상태를 선택해 주세요.');
  if(status==='scheduled')return{game_status:status,holics_score:null,opponent_score:null};
  if(!/^\d{1,3}$/.test(String(holics??''))||!/^\d{1,3}$/.test(String(opponent??'')))throw new GameResultError('두 팀의 점수를 0~999 사이의 정수로 입력해 주세요.');
  const a=Number(holics),b=Number(opponent);
  if(status==='win'&&a<=b||status==='loss'&&a>=b||status==='draw'&&a!==b)throw new GameResultError('선택한 승·패·무승부와 점수가 맞지 않습니다.');
  return{game_status:status,holics_score:a,opponent_score:b};
}
const gameStatus=event=>Object.hasOwn(resultLabels,event.game_status)?event.game_status:'scheduled';
function resultHTML(event){const status=gameStatus(event);return `<p class="calendar-result"><span class="game-result-badge" data-result="${status}">${resultLabels[status]}</span>${status==='scheduled'?'':`<span class="game-score">YB Holics <strong>${event.holics_score} : ${event.opponent_score}</strong> ${esc(event.opponent||'상대팀')}</span>`}</p>`;}
let previewEvents=[];
function eventService(db,preview){
  const rpc=async(name,args)=>{const{data,error}=await db.rpc(name,args);if(error)throw error;return data;};
  if(!preview)return{list:(from,to)=>rpc('get_team_events',{p_from:from,p_to:to}),save:(event,values)=>rpc('save_team_event_with_result',{p_id:event?.id||null,p_revision:event?.revision??0,p_title:values.title,p_date:values.event_date,p_time:values.event_time||null,p_opponent:values.opponent,p_location:values.location,p_memo:values.memo,p_game_status:values.game_status,p_holics_score:values.holics_score,p_opponent_score:values.opponent_score}),remove:event=>rpc('delete_team_event',{p_id:event.id,p_revision:event.revision})};
  return{async list(from,to){return structuredClone(previewEvents.filter(event=>event.event_date>=from&&event.event_date<=to));},async save(event,values){const saved={...values,id:event?.id||crypto.randomUUID(),revision:(event?.revision??0)+1};previewEvents=event?previewEvents.map(item=>item.id===event.id?saved:item):[...previewEvents,saved];return saved;},async remove(event){previewEvents=previewEvents.filter(item=>item.id!==event.id);}};
}

export async function renderCalendar(main,{db,preview=false,canRead,signedIn,canEdit,isCurrent,notify}){
  if(!canRead){main.innerHTML=accessDenied('경기 일정',{signedIn});return;}
  const today=dateKey(new Date()),service=eventService(db,preview);let selected=today,year=Number(today.slice(0,4)),month=Number(today.slice(5,7))-1,events=[],request=0,busy=false;
  main.innerHTML=`<section class="team-calendar"><div class="board-heading"><div><h1>경기 일정</h1><p>YB Holics</p></div>${canEdit?'<button class="primary" id="calendar-add" type="button">일정 등록</button>':''}</div><div class="calendar-toolbar"><button class="secondary" id="calendar-prev" aria-label="이전 달">‹</button><h2 id="calendar-month"></h2><button class="secondary" id="calendar-next" aria-label="다음 달">›</button><button class="secondary" id="calendar-today">오늘</button></div><p class="form-error" id="calendar-error" role="alert"></p><div class="calendar-weekdays" aria-hidden="true">${['일','월','화','수','목','금','토'].map(day=>`<span>${day}</span>`).join('')}</div><div class="calendar-grid" id="calendar-grid" aria-label="경기 일정 달력"></div><section class="calendar-day"><h2 id="calendar-selected"></h2><div id="calendar-events"></div></section>${canEdit?'<dialog class="dialog calendar-dialog" id="calendar-dialog"><div class="dialog-top"><h2 id="calendar-form-title">일정 등록</h2><button class="icon-button" type="button" id="calendar-close" aria-label="닫기">×</button></div><form id="calendar-form"><label>일정 제목<input name="title" maxlength="80" required></label><div class="calendar-form-row"><label>날짜<input type="date" name="event_date" required></label><label>시간<input type="time" name="event_time"></label></div><label>상대팀<input name="opponent" maxlength="50"></label><label>장소<input name="location" maxlength="100"></label><label>경기 결과<select name="game_status"><option value="scheduled">경기 전</option><option value="win">승</option><option value="loss">패</option><option value="draw">무승부</option></select></label><div class="calendar-form-row calendar-score-fields"><label>YB Holics 점수<input type="number" name="holics_score" min="0" max="999" step="1" inputmode="numeric" disabled></label><label>상대팀 점수<input type="number" name="opponent_score" min="0" max="999" step="1" inputmode="numeric" disabled></label></div><label>메모<textarea name="memo" rows="3" maxlength="1000"></textarea></label><p class="form-error" id="calendar-save-error" role="alert"></p><button class="primary full" type="submit" id="calendar-save">저장</button></form></dialog>':''}</section>`;
  const root=main.querySelector('.team-calendar'),alive=()=>isCurrent()&&main.contains(root),find=selector=>root.querySelector(selector);
  function draw(){
    find('#calendar-month').textContent=`${year}년 ${month+1}월`;
    find('#calendar-grid').innerHTML=monthCells(year,month).map(key=>{const dayEvents=events.filter(event=>event.event_date===key);return `<button type="button" class="calendar-cell ${Number(key.slice(5,7))!==month+1?'outside':''} ${key===today?'today':''} ${key===selected?'selected':''}" data-date="${key}" aria-pressed="${key===selected}" aria-label="${key}, 경기 ${dayEvents.length}건"><span class="calendar-date">${Number(key.slice(8))}</span>${dayEvents.slice(0,2).map(event=>`<span class="calendar-event-label" data-result="${gameStatus(event)}">${esc(gameStatus(event)==='scheduled'?event.title:`${resultLabels[gameStatus(event)]} ${event.holics_score}:${event.opponent_score} · ${event.title}`)}</span>`).join('')}${dayEvents.length>2?`<span class="calendar-more">+${dayEvents.length-2}</span>`:''}${dayEvents.length?'<span class="calendar-dot" aria-hidden="true"></span>':''}</button>`;}).join('');
    find('#calendar-selected').textContent=new Date(`${selected}T12:00:00`).toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});
    const dayEvents=events.filter(event=>event.event_date===selected).sort((a,b)=>(a.event_time||'').localeCompare(b.event_time||''));
    find('#calendar-events').innerHTML=dayEvents.length?dayEvents.map(event=>`<article class="calendar-event"><div><h3>${esc(event.title)}</h3><p>${[event.event_time?.slice(0,5),event.opponent?`vs ${event.opponent}`:'',event.location].filter(Boolean).map(esc).join(' · ')||'시간·장소 미정'}</p>${resultHTML(event)}${event.memo?`<p class="calendar-memo">${esc(event.memo)}</p>`:''}</div>${canEdit?`<div class="calendar-event-actions"><button type="button" class="text-button" data-edit-event="${esc(event.id)}">수정</button><button type="button" class="text-button" data-delete-event="${esc(event.id)}">삭제</button></div>`:''}</article>`).join(''):'<p class="calendar-empty">등록된 경기가 없습니다.</p>';
  }
  async function refresh(){const id=++request;find('#calendar-error').textContent='';draw();try{const cells=monthCells(year,month),data=await service.list(cells[0],cells.at(-1));if(!alive()||id!==request)return;events=data;draw();}catch{if(alive()&&id===request)find('#calendar-error').textContent='일정을 불러오지 못했어요. 잠시 후 다시 시도해 주세요.';}}
  function move(delta){if(busy)return;const date=new Date(year,month+delta,1);year=date.getFullYear();month=date.getMonth();selected=dateKey(date);events=[];void refresh();}
  find('#calendar-prev').onclick=()=>move(-1);find('#calendar-next').onclick=()=>move(1);find('#calendar-today').onclick=()=>{if(busy)return;selected=today;year=Number(today.slice(0,4));month=Number(today.slice(5,7))-1;events=[];void refresh();};
  let editing=null;
  function updateScoreFields(){const form=find('#calendar-form'),scheduled=form.elements.game_status.value==='scheduled';for(const key of ['holics_score','opponent_score']){form.elements[key].disabled=scheduled;form.elements[key].required=!scheduled;}}
  function open(event=null){if(busy||!canEdit)return;editing=event;const form=find('#calendar-form');form.reset();for(const key of ['title','event_date','event_time','opponent','location','memo','game_status','holics_score','opponent_score'])form.elements[key].value=event?.[key]??(key==='event_date'?selected:key==='game_status'?'scheduled':'');updateScoreFields();find('#calendar-form-title').textContent=event?'일정 수정':'일정 등록';find('#calendar-save-error').textContent='';find('#calendar-dialog').showModal();}
  find('#calendar-add')?.addEventListener('click',()=>open());find('#calendar-close')?.addEventListener('click',()=>find('#calendar-dialog').close());
  root.onclick=async event=>{
    const date=event.target.closest('[data-date]');if(date&&!busy){selected=date.dataset.date;const selectedMonth=Number(selected.slice(5,7))-1;if(selectedMonth!==month){year=Number(selected.slice(0,4));month=selectedMonth;events=[];void refresh();}else draw();return;}
    const edit=event.target.closest('[data-edit-event]');if(edit){open(events.find(item=>item.id===edit.dataset.editEvent));return;}
    const remove=event.target.closest('[data-delete-event]');if(!remove||!canEdit||busy)return;busy=true;remove.disabled=true;try{await service.remove(events.find(item=>item.id===remove.dataset.deleteEvent));if(!alive())return;notify('일정을 삭제했어요.');await refresh();}catch{if(alive())find('#calendar-error').textContent='삭제하지 못했어요. 새로고침 후 다시 시도해 주세요.';}finally{busy=false;if(alive())remove.disabled=false;}
  };
  const form=find('#calendar-form');if(form)form.elements.game_status.onchange=updateScoreFields;if(form)form.onsubmit=async event=>{event.preventDefault();if(busy||!canEdit)return;busy=true;const button=find('#calendar-save');button.disabled=true;find('#calendar-save-error').textContent='';const values=Object.fromEntries(new FormData(form));for(const key of ['title','opponent','location','memo'])values[key]=values[key].trim();try{Object.assign(values,parseGameResult(values.game_status,values.holics_score,values.opponent_score));const saved=await service.save(editing,values);if(!alive())return;selected=saved.event_date;year=Number(selected.slice(0,4));month=Number(selected.slice(5,7))-1;find('#calendar-dialog').close();notify('일정을 저장했어요.');await refresh();}catch(error){if(alive())find('#calendar-save-error').textContent=error instanceof GameResultError?error.message:'저장하지 못했어요. 날짜와 내용을 확인하고 다시 시도해 주세요.';}finally{busy=false;if(alive())button.disabled=false;}};
  await refresh();
}
